// ── FILE MANAGEMENT ──
function addFile() {
  const name = prompt('File name (e.g., script.js):', 'script.js');
  if (!name) return;
  const ext = name.split('.').pop();
  const template = { html: '<!DOCTYPE html>\n<html>\n<head><title>New</title></head>\n<body>\n  <p>New file</p>\n</body>\n</html>', js: '// New JavaScript file\nconsole.log("loaded");', css: '/* New CSS file */', json: '{}', txt: '' };
  addFileInternal(name, template[ext] || '', ext);
  switchFile(name);
}

function addFileInternal(name, content, ext) {
  if (files[name]) { if(!confirm(`Replace ${name}?`))return; }
  files[name] = { name, content, ext, id: nextFileId++ };
  if (!fileOrder.includes(name)) fileOrder.push(name);
  renderFileTree();
  renderTabs();
}

function deleteFile(name) {
  if (fileOrder.length <= 1) return;
  if (!confirm(`Delete ${name}?`)) return;
  delete files[name];
  fileOrder = fileOrder.filter(f => f !== name);
  if (currentFile === name) switchFile(fileOrder[0]);
  renderFileTree();
  renderTabs();
}

function switchFile(name) {
  currentFile = name;
  const file = files[name];
  if (!file) return;
  document.getElementById('codeEditor').value = file.content;
  updateLineNumbers();
  renderTabs();
  renderFileTree();
}

function onCodeChange() {
  const file = files[currentFile];
  if (file) file.content = document.getElementById('codeEditor').value;
  updateLineNumbers();
}

function getFileIcon(name) {
  const ext = name.split('.').pop();
  return { html: '🌐', js: '📜', css: '🎨', json: '📋', txt: '📄', jsx: '⚛️', ts: '🦾' }[ext] || '📄';
}

// ── RENDER ──
