function renderBoard(){
  const grid=document.getElementById('grid');grid.innerHTML='';
  for(let r=0;r<GRID_SIZE;r++)for(let c=0;c<GRID_SIZE;c++){
    const input=document.createElement('input');input.className='cell';input.type='text';input.maxLength=1;
    input.dataset.r=r;input.dataset.c=c;
    if(board[r]&&board[r][c]!==0){input.value=board[r][c];if(given[r][c])input.classList.add('given')}
    if(given[r][c])input.readOnly=true;
    input.oninput=function(){const v=parseInt(this.value);if(this.value&&(isNaN(v)||v<1||v>9))this.value='';board[parseInt(this.dataset.r)][parseInt(this.dataset.c)]=this.value?parseInt(this.value):0};
    grid.appendChild(input);
  }
  updateStats();
}

function readBoard(){
  const inputs=document.querySelectorAll('.cell');
  inputs.forEach(inp=>{const r=parseInt(inp.dataset.r),c=parseInt(inp.dataset.c);board[r][c]=inp.value?parseInt(inp.value):0});
}

function isValid(b,r,c,num){
  for(let i=0;i<GRID_SIZE;i++){if(b[r][i]===num)return false;if(b[i][c]===num)return false}
  const br=Math.floor(r/BOX_SIZE)*BOX_SIZE,bc=Math.floor(c/BOX_SIZE)*BOX_SIZE;
  for(let i=0;i<BOX_SIZE;i++)for(let j=0;j<BOX_SIZE;j++){if(b[br+i][bc+j]===num)return false}
  return true;
}

function solve(b){stepCount++;for(let r=0;r<GRID_SIZE;r++)for(let c=0;c<GRID_SIZE;c++){
  if(b[r][c]===0){for(let num=1;num<=9;num++){if(isValid(b,r,c,num)){b[r][c]=num;if(solve(b))return true;b[r][c]=0;backtrackCount++}}return false}
}return true}

async function solveSudoku(){
  readBoard();stepCount=0;backtrackCount=0;solving=true;
  document.getElementById('solveStatus').textContent='🔄 Solving...';
  const b=board.map(row=>[...row]);
  setTimeout(()=>{
    const solved=solve(b);
    if(solved){board=b;given=Array(9).fill(null).map(()=>Array(9).fill(true));renderBoard();highlightSolved();document.getElementById('solveStatus').textContent='✅ Solved!'}
    else{document.getElementById('solveStatus').textContent='❌ No solution'}
    solving=false;updateStats();
  },50);
}

