function updateAnim(){
  document.getElementById('durationVal').textContent=document.getElementById('duration').value+'s';
  document.getElementById('delayVal').textContent=document.getElementById('delay').value+'s';
  document.getElementById('startXVal').textContent=document.getElementById('startX').value;
  document.getElementById('endXVal').textContent=document.getElementById('endX').value;
  document.getElementById('startYVal').textContent=document.getElementById('startY').value;
  document.getElementById('endYVal').textContent=document.getElementById('endY').value;
  document.getElementById('startScaleVal').textContent=document.getElementById('startScale').value;
  document.getElementById('endScaleVal').textContent=document.getElementById('endScale').value;
  document.getElementById('startRotVal').textContent=document.getElementById('startRotate').value+'°';
  document.getElementById('endRotVal').textContent=document.getElementById('endRotate').value+'°';
  document.getElementById('startOpVal').textContent=document.getElementById('startOpacity').value;
  document.getElementById('endOpVal').textContent=document.getElementById('endOpacity').value;
  updateCSS();
  playAnimation();
  saveToStorage();
}

function playAnimation(){
  const box=document.getElementById('animBox');
  const dur=document.getElementById('duration').value;
  const ease=document.getElementById('easing').value;
  const delay=document.getElementById('delay').value;
  const iter=document.getElementById('iterations').value;
  const dir=document.getElementById('direction').value;
  const fill=document.getElementById('fillMode').value;
  box.classList.add('playing');
  box.style.animation='none';
  box.offsetHeight;
  box.style.animation=`customAnim ${dur}s ${ease} ${delay}s ${iter} ${dir} ${fill}`;
  setTimeout(()=>box.classList.remove('playing'),(parseFloat(dur)+parseFloat(delay)+0.1)*1000);
}

function updateCSS(){
  const dur=document.getElementById('duration').value;
  const ease=document.getElementById('easing').value;
  const delay=document.getElementById('delay').value;
  const iter=document.getElementById('iterations').value;
  const dir=document.getElementById('direction').value;
  const fill=document.getElementById('fillMode').value;
  const sx=document.getElementById('startX').value,ex=document.getElementById('endX').value;
  const sy=document.getElementById('startY').value,ey=document.getElementById('endY').value;
  const ss=document.getElementById('startScale').value,es=document.getElementById('endScale').value;
  const sr=document.getElementById('startRotate').value,er=document.getElementById('endRotate').value;
  const so=document.getElementById('startOpacity').value,eo=document.getElementById('endOpacity').value;
  let from=`from { opacity: ${so}; transform: translateX(${sx}px) translateY(${sy}px) scale(${ss}) rotate(${sr}deg); }`;
  let to=`to { opacity: ${eo}; transform: translateX(${ex}px) translateY(${ey}px) scale(${es}) rotate(${er}deg); }`;
  if(sx!='0'||sy!='0'||ss!='1'||sr!='0'||so!='1'){} // always show both
  document.getElementById('cssOutput').textContent=
`@keyframes customAnim {\n  ${from}\n  ${to}\n}\n\n.element {\n  animation: customAnim ${dur}s ${ease} ${delay}s ${iter} ${dir} ${fill};\n}`;
