function chips() {
  const s = DATA.summary || {};
  const byLevel = s.by_level || {};
  const fixes = (DATA.fixes || []).filter(f => f.passed_after_repair).length;
  return `
    <div class="chip green"><b>${s.total_done ?? '—'}</b>built</div>
