    <div class="chip"><b>${(DATA.fixes || []).length}</b>datasheet fixes</div>`;
}

function outcomeClass(b) {
  if (b.passed && b.repairs) return 'patch';
  return b.passed ? 'pass' : 'fail';
}
function outcomeLabel(b) {
  if (b.passed && b.repairs) return `PASS +${b.repairs} repair${b.repairs > 1 ? 's' : ''}`;
  return b.passed ? 'PASS' : 'FAIL';
}

function fixFor(id) {
  return (DATA.fixes || []).filter(f => f.id === id);
}

function render() {
  document.getElementById('chips').innerHTML = chips();
  document.getElementById('status').innerHTML =
    `<span>Updated ${DATA.updated}</span>` +
    `<span>Dataset: <a href="/api/build-ladder/dataset" target="_blank">round9-buildladder.jsonl</a></span>` +
    `<span class="live">● API live</span>`;

  let list = (DATA.builds || []).slice();
  if (filter === 'fails') list = list.filter(b => !b.passed);
  else if (filter === 'repaired') list = list.filter(b => b.passed && (b.repairs || b.autoPatch));
  else if (filter !== 'all') list = list.filter(b => b.level === filter);
  if (query) {
    const q = query.toLowerCase();
    list = list.filter(b => (b.request || '').toLowerCase().includes(q) || (b.id || '').toLowerCase().includes(q));
