  try {
    const r = await fetch('/api/build-ladder/retest/' + id, { method: 'POST' });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error || 'retest failed');
    const box = document.createElement('div');
    box.id = 'retestResult';
    box.className = d.ok ? 'ok' : 'bad';
    box.innerHTML = `<b>${d.ok ? '✅ PASS' : '❌ FAIL'}</b> — ${escapeHtml(d.detail || '')}` +
      (d.out ? `<pre style="max-height:160px;overflow:auto;margin-top:6px">${escapeHtml(d.out)}</pre>` : '');
    btn.closest('.actions').appendChild(box);
    setTimeout(() => box.remove(), 20000);
    if (d.ok) await load();
  } catch (e) {
