function getDateKey(d) { return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0'); }

function renderCalendar() {
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  document.getElementById('monthYear').textContent = currentDate.toLocaleDateString('en', { month: 'long', year: 'numeric' });

  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const daysInPrev = new Date(year, month, 0).getDate();

  const todayKey = getDateKey(new Date());
  const container = document.getElementById('calDays');
  container.innerHTML = '';

  // Previous month days
  for (let i = firstDay - 1; i >= 0; i--) {
    const d = daysInPrev - i;
    container.appendChild(createDayCell(new Date(year, month-1, d), true));
  }
  // Current month days
  for (let d = 1; d <= daysInMonth; d++) {
    const date = new Date(year, month, d);
    const cell = createDayCell(date, false);
    if (getDateKey(date) === todayKey) cell.classList.add('today');
    if (selectedDate && getDateKey(date) === getDateKey(selectedDate)) cell.classList.add('selected');
    container.appendChild(cell);
  }
  // Next month days
  const totalCells = firstDay + daysInMonth;
  const remaining = (7 - (totalCells % 7)) % 7;
  for (let d = 1; d <= remaining; d++) {
    container.appendChild(createDayCell(new Date(year, month+1, d), true));
  }
  renderSidePanel();
}

function createDayCell(date, otherMonth) {
  const cell = document.createElement('div');
  cell.className = 'cal-day' + (otherMonth ? ' other-month' : '');
  const dayNum = date.getDate();
  cell.innerHTML = `<div class="day-number">${dayNum}</div>`;
  const key = getDateKey(date);
  const dayEvents = events.filter(e => e.date === key).sort((a,b) => a.time.localeCompare(b.time) || a.title.localeCompare(b.title));
  let eventHtml = '<div class="day-events">';
  const maxShow = 2;
  dayEvents.slice(0, maxShow).forEach(e => {
    const cat = CATEGORIES[e.category] || CATEGORIES.other;
    eventHtml += `<div class="day-event" style="background:${cat.color}22;color:${cat.color};border-left:2px solid ${cat.color}" onclick="event.stopPropagation();selectDate('${key}');openEditModal('${e.id}')">${e.title}</div>`;
  });
  if (dayEvents.length > maxShow) eventHtml += `<div class="event-more" onclick="event.stopPropagation();selectDate('${key}')">+${dayEvents.length - maxShow} more</div>`;
  eventHtml += '</div>';
  cell.innerHTML += eventHtml;
  cell.onclick = () => selectDate(key);
  cell.dataset.date = key;
  return cell;
}

function renderSidePanel() {
  const panel = document.getElementById('panelContent');
  const title = document.getElementById('panelTitle');
  if (!selectedDate) {
    title.textContent = '📋 Events';
    panel.innerHTML = '<div class="empty-state">Select a day to see events</div>'; return;
  }
  const key = getDateKey(selectedDate);
  const dateStr = selectedDate.toLocaleDateString('en', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
  title.textContent = `📋 ${dateStr}`;
  const dayEvents = events.filter(e => e.date === key).sort((a,b) => a.time.localeCompare(b.time));
  if (dayEvents.length === 0) {
    panel.innerHTML = `<div class="empty-state">No events on this day<br><button class="btn btn-primary" style="margin-top:8px;padding:6px 14px;font-size:0.75rem" onclick="openAddModal('${key}')">+ Add Event</button></div>`; return;
  }
  let html = dayEvents.map(e => {
    const cat = CATEGORIES[e.category] || CATEGORIES.other;
    return `<div class="event-item">
      <div class="event-title">${escapeHTML(e.title)}</div>
      <div class="event-time">${e.time ? formatTime(e.time) : 'All day'} · ${cat.icon} ${cat.label}</div>
      ${e.desc ? `<div style="font-size:0.7rem;color:#555;margin-top:4px">${escapeHTML(e.desc)}</div>` : ''}
      <span class="event-cat" style="background:${cat.color}22;color:${cat.color}">${cat.icon} ${cat.label}</span>
      <div class="event-actions">
        <button class="btn-xs btn-edit" onclick="event.stopPropagation();openEditModal('${e.id}')">✏️ Edit</button>
        <button class="btn-xs btn-del" onclick="event.stopPropagation();deleteEvent('${e.id}')">🗑️ Delete</button>
      </div>
    </div>`;
  }).join('');
  html += `<div style="margin-top:12px"><button class="btn btn-primary" style="width:100%;padding:8px;font-size:0.8rem" onclick="openAddModal('${key}')">+ Add Event</button></div>`;
  panel.innerHTML = html;
}

function escapeHTML(str) {
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
}

function formatTime(t) {
  const [h, m] = t.split(':');
  const hour = parseInt(h);
  return (hour % 12 || 12) + ':' + m + (hour >= 12 ? ' PM' : ' AM');
}

