function countNeighbors(x,y){let c=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(dx===0&&dy===0)continue;if(get(x+dx,y+dy))c++}return c}

function stepGen(){
  const newGrid={},surviveArr=survive.split('').map(Number),birthArr=birth.split('').map(Number);
  const cells=new Set();for(const k in grid)if(grid[k]){const[x,y]=k.split(',').map(Number);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)cells.add(key(x+dx,y+dy))}
  for(const k of cells){const[x,y]=k.split(',').map(Number);const n=countNeighbors(x,y);const alive=get(x,y);if(alive&&surviveArr.includes(n))newGrid[k]=1;else if(!alive&&birthArr.includes(n))newGrid[k]=1}
  grid=newGrid;gen++;draw();updateStats();saveToStorage()
}

