function drawLineChart(canvas,data){
  const ctx=canvas.getContext('2d');
  const rect=canvas.parentElement.getBoundingClientRect();
  canvas.width=rect.width||500;canvas.height=220;
  const w=canvas.width,h=canvas.height,pad={top:15,right:15,bottom:25,left:45};
  const cw=w-pad.left-pad.right,ch=h-pad.top-pad.bottom;

  ctx.clearRect(0,0,w,h);
  ctx.fillStyle='#0a0a14';ctx.fillRect(0,0,w,h);

  const vals=data.data.map(d=>d.value);
  const min=Math.min(...vals)*0.95,max=Math.max(...vals)*1.05;

  // Grid
  ctx.strokeStyle='rgba(255,255,255,0.03)';ctx.lineWidth=1;
  for(let i=0;i<=4;i++){
    const y=pad.top+(ch/4)*i;
    ctx.beginPath();ctx.moveTo(pad.left,y);ctx.lineTo(w-pad.right,y);ctx.stroke();
    ctx.fillStyle='#444';ctx.font='9px Arial';ctx.textAlign='right';
    ctx.fillText(Math.round(max-(max-min)/4*i).toLocaleString(),pad.left-4,y+3);
  }

  // Area
