  input.value = '';

  // Add user message
  messages.push({
    id: 'msg_' + Date.now(),
    text,
    sender: 'user',
    time: Date.now(),
  });

  saveData();
  render();

  // Show typing indicator
  const typing = document.getElementById('typingIndicator');
