  const template = { html: '<!DOCTYPE html>\n<html>\n<head><title>New</title></head>\n<body>\n  <p>New file</p>\n</body>\n</html>', js: '// New JavaScript file\nconsole.log("loaded");', css: '/* New CSS file */', json: '{}', txt: '' };
