  if(itemIdx!==-1){
    const item=items[itemIdx];
    if(item.type==='potion'){player.hp=Math.min(player.maxHp,player.hp+rand(4,8));addLog(`🧪 Found a potion! +${Math.min(8,player.maxHp-player.hp)} HP`,`heal`)}
