    else if(item.type==='shield'){player.def+=1;addLog(`🛡️ Found a shield! DEF +1`,`loot`)}
    else if(item.type==='ring'){player.maxHp+=5;player.hp+=5;addLog(`💍 Found a ring of health! Max HP +5`,`loot`)}
    else if(item.type==='gold'){const g=rand(3,10);player.gold+=g;addLog(`💰 Found ${g} gold!`,`loot`)}
