function runAlgorithm(){
  const algo=document.getElementById('algoSelect').value;
  document.getElementById('algoName').textContent=algo;
  resetVisualization();
  vizActive=true;vizSteps=[];vizStep=0;animNodes.clear();animEdges.clear();animPath=[];
  if(algo==='bfs')runBFS();else if(algo==='dfs')runDFS();else if(algo==='dijkstra')runDijkstra();else if(algo==='mst-prim')runPrim();else if(algo==='mst-kruskal')runKruskal();else if(algo==='components')runComponents();else if(algo==='topological')runTopological();
