  if(s.type==='visit'){animNodes.add(s.id);if(s.label)log(s.label)}else if(s.type==='edge'){animEdges.add(`${s.from}-${s.to}`);if(s.label)log(s.label)}else if(s.type==='path'){animPath=s.path;log(s.label)}else if(s.type==='done'){vizActive=false;log(s.label)}else if(s.type==='clear'){animNodes.clear();animEdges.clear();if(s.label)log(s.label)}
