function loadData() {
  try { const d = localStorage.getItem('ht-data'); if (d) habits = JSON.parse(d); } catch {}
}
function saveData() { localStorage.setItem('ht-data', JSON.stringify(habits)); renderAll(); }

function getDateKey(date) { return date.toISOString().slice(0, 10); }
function todayKey() { return getDateKey(new Date()); }

function toggleHabit(id) {
  const habit = habits.find(h => h.id === id);
  if (!habit) return;
  if (!habit.log) habit.log = {};
  const key = todayKey();
  if (habit.log[key]) delete habit.log[key];
  else habit.log[key] = true;
  saveData();
  renderAll();
}

function getStreak(habit) {
  if (!habit.log || !Object.keys(habit.log).length) return 0;
  let streak = 0;
  const d = new Date();
  while (true) {
    const key = getDateKey(d);
    if (habit.log[key]) streak++;
    else if (streak > 0) break;
    else { d.setDate(d.getDate() - 1); continue; }
    d.setDate(d.getDate() - 1);
  }
  return streak;
}

function renderAll() {
  renderStats();
  renderHabits();
  renderHeatmap();
}

function renderStats() {
  document.getElementById('totalHabits').textContent = habits.length;
  const best = habits.reduce((max, h) => Math.max(max, getStreak(h)), 0);
  document.getElementById('bestStreak').textContent = best;
  const key = todayKey();
  const done = habits.filter(h => h.log && h.log[key]).length;
  document.getElementById('doneToday').textContent = done;
  let totalChecks = 0, doneChecks = 0;
  habits.forEach(h => {
    if (!h.log) return;
    Object.values(h.log).forEach(v => { totalChecks++; if (v) doneChecks++; });
  });
  document.getElementById('completionRate').textContent = totalChecks ? Math.round((doneChecks / totalChecks) * 100) + '%' : '0%';
}

