function getStreakForDay(habit, date) {
  let streak = 0;
  const d = new Date(date);
  while (true) {
    const key = getDateKey(d);
    if (habit.log && habit.log[key]) { streak++; d.setDate(d.getDate() - 1); }
    else break;
  }
  return streak;
}

