function buildHuffman(){
  const text=document.getElementById('inputText').value;
  if(!text){clearAll();return}
  // Count frequencies
  freqs={};for(const ch of text)freqs[ch]=(freqs[ch]||0)+1;
  // Build leaf nodes
  let nodes=Object.entries(freqs).map(([ch,freq])=>({ch,freq,left:null,right:null}));
  steps=[nodes.map(n=>({...n}))]; // snapshot
  // Build tree
  while(nodes.length>1){
    nodes.sort((a,b)=>a.freq-b.freq);
    const left=nodes.shift(),right=nodes.shift();
    const parent={ch:'',freq:left.freq+right.freq,left,right};
    nodes.push(parent);
    steps.push(nodes.map(n=>deepClone(n)));
  }
  tree=nodes[0]||null;
  // Generate codes
  codes={};
  function traverse(node,prefix=''){if(!node)return;if(node.ch&&!node.left&&!node.right)codes[node.ch]=prefix||'0';traverse(node.left,prefix+'0');traverse(node.right,prefix+'1')}
  traverse(tree);
  // Update UI
  currentStep=steps.length-1;
  const slider=document.getElementById('stepSlider');slider.max=Math.max(0,steps.length-1);slider.value=currentStep;
  document.getElementById('stepLabel').textContent=`Step ${currentStep}/${steps.length-1}`;
  drawTree();
  updateCodeTable();
  updateEncodedOutput(text);
  saveToStorage();
}

function deepClone(obj){return JSON.parse(JSON.stringify(obj))}

function updateStep(){
  currentStep=parseInt(document.getElementById('stepSlider').value);
  document.getElementById('stepLabel').textContent=`Step ${currentStep}/${steps.length-1}`;
  drawTree();
}

function drawTree(){
  ctx.clearRect(0,0,W,H);
  if(steps.length===0||currentStep<0||!steps[currentStep])return;
  const currentNodes=steps[currentStep];
  if(!currentNodes||currentNodes.length===0)return;
  // Draw each tree in the forest
  const spacing=W/(currentNodes.length+1);
  currentNodes.forEach((node,i)=>{
    const cx=spacing*(i+1),y=30;
    drawNode(node,cx,y,W*0.35,0);
  });
  // Draw legend
  ctx.fillStyle='#555';ctx.font='8px sans-serif';ctx.textAlign='left';
  ctx.fillText('○ = Internal node (combined freq)',10,H-14);
  ctx.fillText('□ = Leaf node (character + freq)',10,H-4);
}

function drawNode(node,x,y,maxW,depth){
  if(!node)return;
  const isLeaf=node.ch&&!node.left&&!node.right;
  const r=isLeaf?8:6;
  // Draw children first
  if(node.left&&node.right){
    const childY=y+45;const gap=Math.max(20,maxW/2);
    const lx=x-gap, rx=x+gap;
    ctx.strokeStyle='rgba(255,255,255,0.1)';ctx.lineWidth=1;
    ctx.beginPath();ctx.moveTo(x,y+r);ctx.lineTo(lx,childY-r);ctx.stroke();
    ctx.fillStyle='#555';ctx.font='7px monospace';ctx.textAlign='center';
    ctx.fillText('0',(x+lx)/2,(y+childY)/2);
    drawNode(node.left,lx,childY,gap*0.8,depth+1);
    ctx.beginPath();ctx.moveTo(x,y+r);ctx.lineTo(rx,childY-r);ctx.stroke();
    ctx.fillText('1',(x+rx)/2,(y+childY)/2);
    drawNode(node.right,rx,childY,gap*0.8,depth+1);
  }
  // Draw this node
  if(isLeaf){
    ctx.fillStyle='#1a1a2e';ctx.strokeStyle='#00d9ff';ctx.lineWidth=1.5;
    ctx.beginPath();ctx.arc(x,y,r*1.5,0,Math.PI*2);ctx.fill();ctx.stroke();
    ctx.fillStyle='#00d9ff';ctx.font='7px monospace';ctx.textAlign='center';
    const label=node.ch===' '?'␣':node.ch;
    ctx.fillText(label,x,y-3);
    ctx.fillStyle='#555';ctx.font='6px sans-serif';
    ctx.fillText(node.freq,x,y+10);
  }else{
    ctx.fillStyle='rgba(0,217,255,0.08)';ctx.strokeStyle='rgba(0,217,255,0.2)';ctx.lineWidth=1;
    ctx.beginPath();ctx.arc(x,y,r*2,0,Math.PI*2);ctx.fill();ctx.stroke();
    ctx.fillStyle='#888';ctx.font='6px sans-serif';ctx.textAlign='center';
    ctx.fillText(node.freq,x,y+2);
  }
}

function updateCodeTable(){
  const table=document.getElementById('codeTable');
  const sorted=Object.entries(codes).sort((a,b)=>freqs[b[0]]-freqs[a[0]]);
  if(!sorted.length){table.innerHTML='<div style="padding:8px;color:#555;font-size:0.5rem">No data</div>';return}
  let html='<table><tr><th>Char</th><th>Freq</th><th>Code</th><th>Length</th></tr>';
  for(const [ch,code]of sorted){
    const display=ch===' '?'␣':ch==='\n'?'\\n':ch;
    html+=`<tr><td class="char-cell">${escapeHTML(display)}</td><td>${freqs[ch]}</td><td style="font-family:monospace;color:#4ade80">${escapeHTML(code)}</td><td>${code.length}</td></tr>`;
  }
  html+='</table>';
  table.innerHTML=html;
}

function updateEncodedOutput(text){
  let encoded='';for(const ch of text)encoded+=codes[ch]||'';
  document.getElementById('encodedOutput').textContent=encoded||'—';
  const origBits=text.length*8;
  const encBits=encoded.length;
  document.getElementById('originalBits').textContent=origBits;
  document.getElementById('encodedBits').textContent=encBits;
  document.getElementById('compressionRatio').textContent=origBits>0?`${((1-encBits/origBits)*100).toFixed(1)}%`:'0%';
  // Decode
  let decoded='',node=tree;
  if(tree&&!tree.left&&!tree.right){decoded=tree.ch.repeat(text.length)}else{
    for(const bit of encoded){node=bit==='0'?node.left:node.right;if(!node){break}if(node.ch&&!node.left&&!node.right){decoded+=node.ch;node=tree}}
  }
  document.getElementById('decodedOutput').textContent=decoded||'—';
}

