function handlePixel(e){
  const r=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)/cellSize),y=Math.floor((e.clientY-r.top)/cellSize);
  if(x<0||x>=gridSize||y<0||y>=gridSize)return;
  const i=y*gridSize+x;
  if(tool==='pencil'){pixels[i]=primaryColor;drawGrid()}
  else if(tool==='eraser'){pixels[i]=false;drawGrid()}
  else if(tool==='fill'){floodFill(x,y,primaryColor);drawGrid()}
  else if(tool==='eyedropper'){if(pixels[i])primaryColor=pixels[i];document.getElementById('primaryColor').value=primaryColor;drawGrid()}
}

function floodFill(sx,sy,color){
  const target=pixels[sy*gridSize+sx];
  if(target===color)return;
  const queue=[[sx,sy]],visited=new Set();
  while(queue.length>0){
    const [x,y]=queue.shift(),k=`${x},${y}`;
    if(x<0||x>=gridSize||y<0||y>=gridSize||visited.has(k))continue;
    const i=y*gridSize+x;
    if(pixels[i]!==target)continue;
    visited.add(k);pixels[i]=color;
    queue.push([x-1,y],[x+1,y],[x,y-1],[x,y+1]);
  }
}

function drawGrid(){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  ctx.fillStyle='#0a0a14';ctx.fillRect(0,0,canvas.width,canvas.height);
  for(let y=0;y<gridSize;y++)for(let x=0;x<gridSize;x++){
    const c=pixels[y*gridSize+x];if(c){ctx.fillStyle=c;ctx.fillRect(x*cellSize,y*cellSize,cellSize,cellSize)}
  }
  ctx.strokeStyle='rgba(255,255,255,0.04)';ctx.lineWidth=0.5;
  for(let i=0;i<=gridSize;i++){ctx.beginPath();ctx.moveTo(i*cellSize,0);ctx.lineTo(i*cellSize,gridSize*cellSize);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i*cellSize);ctx.lineTo(gridSize*cellSize,i*cellSize);ctx.stroke()}
}

