function generateData(days) {
  const data = [];
  let value = 50000 + Math.random() * 20000;
  for (let i = days - 1; i >= 0; i--) {
    const change = (Math.random() - 0.48) * 0.1;
    value = value * (1 + change);
    data.push({
      date: new Date(Date.now() - i * 86400000),
      value: Math.round(value * 100) / 100,
    });
  }
  return data;
}

