function addItem(){const w=Math.floor(Math.random()*5)+2,v=Math.floor(Math.random()*10)+5;items.push({w,v});renderItems();saveToStorage()}
function resetItems(){items=[{w:3,v:7},{w:4,v:9},{w:5,v:12},{w:2,v:6},{w:6,v:14}];dp=[];selected=[];render();saveToStorage()}
document.getElementById('capSlider').oninput=function(){cap=parseInt(this.value);document.getElementById('capDisplay').textContent=cap;render();saveToStorage()}

function solve(){
  const n=items.length;dp=Array(n+1).fill(null).map(()=>Array(cap+1).fill(0));
  for(let i=1;i<=n;i++)for(let w=0;w<=cap;w++){if(items[i-1].w<=w)dp[i][w]=Math.max(dp[i-1][w],dp[i-1][w-items[i-1].w]+items[i-1].v);else dp[i][w]=dp[i-1][w]}
  // Backtrack
  selected=[];let i=n,w=cap;
  while(i>0&&w>0){if(dp[i][w]!==dp[i-1][w]){selected.push(i-1);w-=items[i-1].w}i--}
  render();document.getElementById('stepDisplay').textContent=n*cap;document.getElementById('maxValDisplay').textContent=dp[n][cap];document.getElementById('selectedDisplay').textContent=selected.map(i=>`Item ${i+1}`).join(', ');saveToStorage()
}

function stepSolve(){
  if(!solving){solving=true;stepIdx=0;dp=Array(items.length+1).fill(null).map(()=>Array(cap+1).fill(0));selected=[]}
  const n=items.length;
  for(let s=0;s<5&&stepIdx<n*(cap+1);s++){
    const i=Math.floor(stepIdx/(cap+1))+1,w=stepIdx%(cap+1);
    if(i<=n&&w<=cap){if(items[i-1].w<=w)dp[i][w]=Math.max(dp[i-1][w],dp[i-1][w-items[i-1].w]+items[i-1].v);else dp[i][w]=dp[i-1][w]}
    stepIdx++;
  }
  if(stepIdx>=n*(cap+1)){solving=false;document.getElementById('stepDisplay').textContent=stepIdx;document.getElementById('maxValDisplay').textContent=dp[n][cap];saveToStorage()}
  render();
}

