function escapeHTML(str) {
  return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function renderMarkdown(text) {
  let html = '';
  // Escape HTML first
  text = escapeHTML(text);

  // Split into lines
  const lines = text.split('\n');
  let inCodeBlock = false;
  let codeBuffer = [];
  let inTable = false;
  let tableBuffer = [];
  let inList = false;
  let result = [];

  for (let i = 0; i < lines.length; i++) {
    let line = lines[i];

    // Code blocks
    if (line.startsWith('```')) {
      if (inCodeBlock) {
        result.push(`<pre><code>${codeBuffer.join('\n')}</code></pre>`);
        codeBuffer = [];
        inCodeBlock = false;
      } else {
        inCodeBlock = true;
      }
      continue;
    }
    if (inCodeBlock) {
      codeBuffer.push(line);
      continue;
    }

    // Horizontal rule
    if (/^(-{3,}|\*{3,}|_{3,})$/.test(line)) {
      result.push('<hr>');
      continue;
    }

    // Headings
    if (line.startsWith('###### ')) { result.push('<h6>' + processInline(line.slice(7)) + '</h6>'); continue; }
    if (line.startsWith('##### ')) { result.push('<h5>' + processInline(line.slice(6)) + '</h5>'); continue; }
    if (line.startsWith('#### ')) { result.push('<h4>' + processInline(line.slice(5)) + '</h4>'); continue; }
    if (line.startsWith('### ')) { result.push('<h3>' + processInline(line.slice(4)) + '</h3>'); continue; }
    if (line.startsWith('## ')) { result.push('<h2>' + processInline(line.slice(3)) + '</h2>'); continue; }
    if (line.startsWith('# ')) { result.push('<h1>' + processInline(line.slice(2)) + '</h1>'); continue; }

    // Blockquotes
    if (line.startsWith('> ')) {
      result.push('<blockquote>' + processInline(line.slice(2)) + '</blockquote>');
      continue;
    }

    // Images
    line = line.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1" loading="lazy">');

    // Tables
    if (line.includes('|') && line.split('|').filter(s => s.trim()).length > 0) {
      if (line.trim().match(/^[\|:\- ]+$/)) {
        // Separator row - skip
        continue;
      }
      if (!inTable) {
        inTable = true;
        tableBuffer = [];
      }
      const cells = line.split('|').map(c => c.trim()).filter(c => c);
      tableBuffer.push(cells);
      continue;
    } else {
      if (inTable && tableBuffer.length > 0) {
        result.push(buildTable(tableBuffer));
        inTable = false;
        tableBuffer = [];
      }
    }

    // Lists
    const ulMatch = line.match(/^(\s*)[\-\*\+]\s+(.*)/);
    const olMatch = line.match(/^(\s*)\d+\.\s+(.*)/);

    if (ulMatch || olMatch) {
      const match = ulMatch || olMatch;
      const indent = match[1].length;
      const content = match[2];
      const isOrdered = !!olMatch;

      if (!inList) {
        inList = true;
        result.push(isOrdered ? '<ol>' : '<ul>');
      }
      result.push(`${'  '.repeat(indent)}<li>${processInline(content)}</li>`);
      continue;
    } else {
      if (inList) {
        const lastResult = result[result.length - 1];
        result.push('</ul></li>');
        inList = false;
      }
    }

    // Empty line
    if (line.trim() === '') {
      result.push('');
      continue;
    }

    // Paragraph
    result.push('<p>' + processInline(line) + '</p>');
  }

  // Close any open blocks
  if (inCodeBlock) result.push('<pre><code>' + codeBuffer.join('\n') + '</code></pre>');
  if (inTable && tableBuffer.length > 0) result.push(buildTable(tableBuffer));
  if (inList) result.push(inList === 'ol' ? '</ol>' : '</ul>');

  return result.join('\n');
}

function processInline(text) {
  // Images (already processed)
  // Links
  text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank">$1</a>');
  // Bold + Italic
  text = text.replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>');
  // Bold
  text = text.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  text = text.replace(/__(.+?)__/g, '<strong>$1</strong>');
  // Italic
  text = text.replace(/\*(.+?)\*/g, '<em>$1</em>');
  text = text.replace(/_(.+?)_/g, '<em>$1</em>');
  // Inline code
  text = text.replace(/`([^`]+)`/g, '<code>$1</code>');
  // Strikethrough
  text = text.replace(/~~(.+?)~~/g, '<del>$1</del>');
  return text;
}

function buildTable(rows) {
  let html = '<table>\n';
  rows.forEach((row, i) => {
    const tag = i === 0 ? 'th' : 'td';
    html += '<tr>';
    row.forEach(cell => {
      html += `<${tag}>${processInline(cell)}</${tag}>`;
    });
    html += '</tr>\n';
  });
  html += '</table>';
  return html;
}

