const canvas=document.getElementById('mazeCanvas'),ctx=canvas.getContext('2d');
const SIZE=21,CELL=16,WALL=2;
let maze=[],visited=[],path=[],solving=false;

function init(){
  canvas.width=SIZE*CELL;canvas.height=SIZE*CELL;
  generateMaze();
}

// DFS maze generation
function generateMaze(){
  solving=false;
  maze=Array(SIZE).fill(null).map(()=>Array(SIZE).fill(1));
  function carve(x,y){maze[y][x]=0;const dirs=[[2,0],[-2,0],[0,2],[0,-2]].sort(()=>Math.random()-0.5);
    for(const[dx,dy]of dirs){const nx=x+dx,ny=y+dy;if(nx>0&&nx<SIZE-1&&ny>0&&ny<SIZE-1&&maze[ny][nx]===1){maze[ny][nx]=0;maze[y+dy/2][x+dx/2]=0;carve(nx,ny)}}}
  carve(1,1);
  maze[0][1]=0;maze[SIZE-1][SIZE-2]=0; // Entrance/Exit
  visited=[];path=[];
  document.getElementById('statusDisplay').textContent='✅ Generated';
  document.getElementById('stepDisplay').textContent='0';
  document.getElementById('pathDisplay').textContent='-';
  draw();saveToStorage();
}

async function solveBFS(){await solve('bfs')}
async function solveAStar(){await solve('astar')}
async function solveDFS(){await solve('dfs')}

async function solve(type){
  if(solving)return;solving=true;clearPaths();
  const speed=parseInt(document.getElementById('speedSlider').value);
  document.getElementById('speedVal').textContent=speed;
  document.getElementById('statusDisplay').textContent=`🔄 ${type.toUpperCase()}...`;

  const start={x:1,y:1},end={x:SIZE-2,y:SIZE-2};
  const queue=type==='dfs'?[start]:[start];
  const parent={};
  const key=p=>`${p.x},${p.y}`;
  parent[key(start)]=null;
  visited=[start];
  let found=false,stepCount=0;

  const delay=speed>0?Math.max(1,50-speed*0.9):0;

  while(queue.length>0&&!found){
    const current=type==='bfs'?queue.shift():type==='dfs'?queue.pop():queue.shift();
    stepCount++;

    if(current.x===end.x&&current.y===end.y){found=true;reconstructPath(parent,current);break;}

    const dirs=[[0,-1],[1,0],[0,1],[-1,0]];
    if(type==='astar'){dirs.sort((a,b)=>{const da=Math.abs(current.x+a[0]-end.x)+Math.abs(current.y+a[1]-end.y);const db=Math.abs(current.x+b[0]-end.x)+Math.abs(current.y+b[1]-end.y);return da-db})}

    for(const[dx,dy]of dirs){
      const nx=current.x+dx,ny=current.y+dy;
      if(nx>=0&&nx<SIZE&&ny>=0&&ny<SIZE&&maze[ny][nx]===0&&!visited.some(v=>v.x===nx&&v.y===ny)){
        visited.push({x:nx,y:ny});
        parent[key({x:nx,y:ny})]=current;
        queue.push({x:nx,y:ny});
      }
    }

    if(delay>0&&stepCount%5===0){draw();await new Promise(r=>setTimeout(r,Math.min(delay,30)))}
  }

  draw();
  document.getElementById('stepDisplay').textContent=stepCount;
  document.getElementById('statusDisplay').textContent=found?'✅ Path found!':'❌ No path';
  solving=false;saveToStorage();
}

function reconstructPath(parent,end){
  path=[];let current=end;
  while(current){path.unshift(current);current=parent[`${current.x},${current.y}`]}
  document.getElementById('pathDisplay').textContent=`${path.length} cells`;
}

function clearPaths(){visited=[];path=[];draw()}

function draw(){
