function play() {
  isPlaying = true;
  document.getElementById('playBtn').textContent = '⏸';
  document.getElementById('artwork').classList.add('playing');
  if (interval) clearInterval(interval);
  interval = setInterval(() => {
    currentTime++;
    if (currentTime >= PLAYLIST[currentTrack].duration) {
      if (repeat === 'one') {
        currentTime = 0;
      } else if (repeat === 'all') {
        nextTrack();
      } else {
        if (currentTrack < PLAYLIST.length - 1) {
          nextTrack();
        } else {
          pause();
          currentTime = 0;
          updateProgress();
        }
      }
    }
    updateProgress();
  }, 1000);
}

function pause() {
  isPlaying = false;
  document.getElementById('playBtn').textContent = '▶';
  document.getElementById('artwork').classList.remove('playing');
  if (interval) {
    clearInterval(interval);
    interval = null;
  }
}

function nextTrack() {
  let next;
  if (shuffle) {
    do {
      next = Math.floor(Math.random() * PLAYLIST.length);
    } while (next === currentTrack && PLAYLIST.length > 1);
  } else {
    next = currentTrack + 1;
  }
  if (next >= PLAYLIST.length) next = 0;
  loadTrack(next);
  if (isPlaying) {
    clearInterval(interval);
    interval = setInterval(tick, 1000);
  }
}

function prevTrack() {
  let prev;
  if (shuffle) {
    do {
      prev = Math.floor(Math.random() * PLAYLIST.length);
    } while (prev === currentTrack && PLAYLIST.length > 1);
  } else {
    prev = currentTrack - 1;
  }
  if (prev < 0) prev = PLAYLIST.length - 1;
  loadTrack(prev);
  if (isPlaying) {
    clearInterval(interval);
    interval = setInterval(tick, 1000);
  }
}

function tick() {
  currentTime++;
  if (currentTime >= PLAYLIST[currentTrack].duration) {
    if (repeat === 'one') {
      currentTime = 0;
    } else {
      nextTrack();
    }
  }
  updateProgress();
}

