  if (!audioCtx) {
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    masterGain = audioCtx.createGain();
    masterGain.gain.value = 0.8;
    masterGain.connect(audioCtx.destination);

    reverbNode = audioCtx.createConvolver();
    delayNode = audioCtx.createDelay(0.5);
    filterNode = audioCtx.createBiquadFilter();
    filterNode.type = 'lowpass';
    filterNode.frequency.value = 2000;

    // Simple reverb using impulse response
    const irLen = audioCtx.sampleRate * 1.5;
    const irBuffer = audioCtx.createBuffer(2, irLen, audioCtx.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const data = irBuffer.getChannelData(ch);
      for (let i = 0; i < irLen; i++) data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / irLen, 3);
    }
    reverbNode.buffer = irBuffer;

    masterGain.connect(filterNode);
    filterNode.connect(reverbNode);
    filterNode.connect(delayNode);
    reverbNode.connect(masterGain);
    delayNode.connect(masterGain);
    delayNode.delayTime.value = 0.15;
  }
  updateParams();
}

function getFrequency(note, octave) {
  if (note === 'C_up' || note === 'C#_up') {
    octave++;
    note = note === 'C_up' ? 'C' : 'C#';
  }
  const base = NOTE_FREQS[note];
  return base ? base * Math.pow(2, octave - 4) : 440;
}

function playNote(note, octave) {
  initAudio();
  if (audioCtx.state === 'suspended') audioCtx.resume();

  const freq = getFrequency(note, octave);
  const key = note + octave;
  if (activeOscillators[key]) return;

  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();

  osc.type = currentWave;
  osc.frequency.value = freq;

  gain.gain.value = masterGain.gain.value * 0.15;
  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.5);

  osc.connect(gain);
  gain.connect(filterNode);

  osc.start();
  osc.stop(audioCtx.currentTime + 0.5);
  activeOscillators[key] = { osc, gain };

  setTimeout(() => { delete activeOscillators[key]; }, 600);

  document.getElementById('currentNote').textContent = note + octave;
  highlightKeyboard(note, true);
}

function stopNote(note, octave) {
  const key = note + octave;
  if (activeOscillators[key]) {
    activeOscillators[key].gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.05);
    setTimeout(() => {
      if (activeOscillators[key]) {
        activeOscillators[key].osc.stop();
        delete activeOscillators[key];
      }
    }, 100);
  }
  highlightKeyboard(note, false);
}

