const DURATIONS = { pomodoro: 25 * 60, short: 5 * 60, long: 15 * 60 };
const CIRCUMFERENCE = 2 * Math.PI * 115;

let mode = 'pomodoro';
let timeLeft = DURATIONS.pomodoro;
let isRunning = false;
let timerInterval = null;
let completedSessions = 0;
let todayMinutes = 0;

function setMode(newMode) {
  if (isRunning) return;
  mode = newMode;
  document.querySelectorAll('.mode-btn').forEach(b => b.classList.toggle('active', b.dataset.mode === mode));
  timeLeft = DURATIONS[mode];
  updateDisplay();
  updateProgress(1);
  updateLabel();
}

var startTime = 0;
var targetDuration = DURATIONS.pomodoro;

function toggleTimer() {
  if (isRunning) {
    pauseTimer();
  } else {
    startTimer();
  }
}

function startTimer() {
  if (timeLeft <= 0) {
    timeLeft = DURATIONS[mode];
  }
  isRunning = true;
  startTime = Date.now();
  targetDuration = timeLeft;
  document.getElementById('startBtn').textContent = '⏸ Pause';
  document.getElementById('startBtn').className = 'btn btn-pause';
  timerInterval = setInterval(function() {
    var elapsed = Math.floor((Date.now() - startTime) / 1000);
    timeLeft = targetDuration - elapsed;
    if (timeLeft <= 0) {
      clearInterval(timerInterval);
      timerInterval = null;
      isRunning = false;
      timeLeft = 0;
      updateDisplay();
      updateProgress(0);
      onComplete();
      return;
    }
    updateDisplay();
    updateProgress(timeLeft / targetDuration);
    document.title = formatTime(timeLeft) + ' - Pomodoro';
  }, 200);
}

function pauseTimer() {
  clearInterval(timerInterval);
  timerInterval = null;
  isRunning = false;
  document.getElementById('startBtn').textContent = '▶ Resume';
  document.getElementById('startBtn').className = 'btn btn-start';
}

function resetTimer() {
  clearInterval(timerInterval);
  timerInterval = null;
  isRunning = false;
  timeLeft = DURATIONS[mode];
  document.getElementById('startBtn').textContent = '▶ Start';
  document.getElementById('startBtn').className = 'btn btn-start';
  updateDisplay();
  updateProgress(1);
  updateLabel();
}

function onComplete() {
  completedSessions++;
  todayMinutes += DURATIONS[mode] / 60;
  document.getElementById('sessions').textContent = completedSessions;
  document.getElementById('todayMinutes').textContent = Math.round(todayMinutes);

  if (mode === 'pomodoro') {
    if (completedSessions % 4 === 0) {
      setMode('long');
      document.body.style.borderTop = '3px solid #4ade80';
    } else {
      setMode('short');
    }
  } else {
    setMode('pomodoro');
  }

  document.getElementById('startBtn').textContent = '▶ Start';
  document.getElementById('startBtn').className = 'btn btn-start';
  showNotification();
}

function showNotification() {
  if ('Notification' in window && Notification.permission === 'granted') {
    new Notification('Pomodoro Complete! 🎉', {
      body: mode === 'pomodoro' ? 'Great focus! Time for a break.' : 'Break over! Ready to focus again.',
    });
  }
}

function updateDisplay() {
  const m = Math.floor(timeLeft / 60);
  const s = timeLeft % 60;
  document.getElementById('timerDisplay').textContent = `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  document.title = `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')} - Pomodoro`;
}

function updateProgress(ratio) {
  const offset = CIRCUMFERENCE * (1 - ratio);
  const progress = document.getElementById('progress');
  progress.style.strokeDashoffset = offset;
  progress.classList.toggle('break-mode', mode !== 'pomodoro');
}

function updateLabel() {
  const labels = { pomodoro: '🎯 Focus Time', short: '☕ Short Break', long: '🌴 Long Break' };
  document.getElementById('timerLabel').textContent = labels[mode] || 'Focus Time';
}

if ('Notification' in window && Notification.permission === 'default') {
  Notification.requestPermission();
}

