function isFormula(val) { return typeof val === 'string' && val.startsWith('='); }

function evaluateFormula(formula) {
  try {
    let expr = formula.slice(1);
    // Handle SUM
    expr = expr.replace(/SUM\(([A-Z]+)(\d+):([A-Z]+)(\d+)\)/gi, (m, c1, r1, c2, r2) => {
      let sum = 0;
      const startR = parseInt(r1) - 1, endR = parseInt(r2) - 1;
      const startC = c1.charCodeAt(0) - 65, endC = c2.charCodeAt(0) - 65;
      for (let r = startR; r <= endR; r++)
        for (let c = startC; c <= endC; c++) {
          const v = parseFloat(getCell(r, c));
          if (!isNaN(v)) sum += v;
        }
      return sum;
    });
    // Handle AVERAGE
    expr = expr.replace(/AVERAGE\(([A-Z]+)(\d+):([A-Z]+)(\d+)\)/gi, (m, c1, r1, c2, r2) => {
      let sum = 0, count = 0;
      const startR = parseInt(r1) - 1, endR = parseInt(r2) - 1;
      const startC = c1.charCodeAt(0) - 65, endC = c2.charCodeAt(0) - 65;
      for (let r = startR; r <= endR; r++)
        for (let c = startC; c <= endC; c++) {
          const v = parseFloat(getCell(r, c));
          if (!isNaN(v)) { sum += v; count++; }
        }
      return count ? sum / count : 0;
    });
    // Handle MAX/MIN
    expr = expr.replace(/(MAX|MIN)\(([A-Z]+)(\d+):([A-Z]+)(\d+)\)/gi, (m, op, c1, r1, c2, r2) => {
      const startR = parseInt(r1) - 1, endR = parseInt(r2) - 1;
      const startC = c1.charCodeAt(0) - 65, endC = c2.charCodeAt(0) - 65;
      let result = op.toUpperCase() === 'MAX' ? -Infinity : Infinity;
      for (let r = startR; r <= endR; r++)
        for (let c = startC; c <= endC; c++) {
          const v = parseFloat(getCell(r, c));
          if (!isNaN(v)) result = op.toUpperCase() === 'MAX' ? Math.max(result, v) : Math.min(result, v);
        }
      return result === -Infinity || result === Infinity ? 0 : result;
    });
    // Handle COUNT
    expr = expr.replace(/COUNT\(([A-Z]+)(\d+):([A-Z]+)(\d+)\)/gi, (m, c1, r1, c2, r2) => {
      let count = 0;
      const startR = parseInt(r1) - 1, endR = parseInt(r2) - 1;
      const startC = c1.charCodeAt(0) - 65, endC = c2.charCodeAt(0) - 65;
      for (let r = startR; r <= endR; r++)
        for (let c = startC; c <= endC; c++) {
          if (getCell(r, c) !== '') count++;
        }
      return count;
    });
    // Replace cell references
    expr = expr.replace(/([A-Z]+)(\d+)/g, (m, col, row) => {
      const c = col.toUpperCase().charCodeAt(0) - 65;
      const r = parseInt(row) - 1;
      const v = getCell(r, c);
      if (v === '' || v.startsWith('=')) return '0';
      return parseFloat(v) || 0;
    });
    const result = Function('"use strict"; return (' + expr + ')')();
    return isNaN(result) ? '#VALUE!' : result;
  } catch (e) { return '#ERROR!'; }
}

