let cwd='/home/user';
let currentUser='user';

function getNode(path){
  let parts=path.split('/').filter(Boolean);
  let node=fs['/'];
  for(const p of parts){
    if(!node||node.type!=='dir'||!node.children[p])return null;
    node=node.children[p];
  }
  return node;
}

function resolvePath(p){
  if(p.startsWith('/'))return p;
  if(p.startsWith('~'))return '/home/user'+p.slice(1);
  let cur=cwd;
  const parts=p.split('/').filter(Boolean);
  for(const part of parts){
    if(part==='..'){const idx=cur.lastIndexOf('/');cur=idx>0?cur.slice(0,idx):'/'}
    else if(part==='.')continue;
    else cur=cur+(cur.endsWith('/')?'':'/')+part;
  }
  return cur;
}

function getDirContents(dirPath){
  const node=getNode(dirPath);
  if(!node||node.type!=='dir')return null;
  return node.children||{};
}

