const COMMANDS={};

function register(name,fn,help){
  COMMANDS[name]=fn;
  COMMANDS[name].help=help;
}

function print(text,cls='out'){
  const d=document.createElement('div');d.className=cls;d.innerHTML=text;term.appendChild(d);
}

register('help',(args)=>{
  print('<span style="color:#00d9ff">╔══════════════════════════════════════╗</span>','');
  print('<span style="color:#00d9ff">║        AVAILABLE COMMANDS            ║</span>','');
  print('<span style="color:#00d9ff">╚══════════════════════════════════════╝</span>','');
  for(const [name,fn] of Object.entries(COMMANDS)){
    print(`  <span style="color:#4ade80">${name.padEnd(12)}</span> ${fn.help||''}`, ' ');
  }
},'Show this help message');

register('ls',(args)=>{
  const target=args[0]||cwd;
  const resolved=resolvePath(target);
  const contents=getDirContents(resolved);
  if(!contents){print(`ls: cannot access '${target}': No such directory`,'err');return}
  if(args.includes('-la')||args.includes('-l')){
    for(const [name,node] of Object.entries(contents)){
      const perms=node.type==='dir'?'drwxr-xr-x':'-rw-r--r--';
      const size=node.type==='file'?(node.content||'').length:4096;
      print(`${perms} 1 user user ${String(size).padStart(6)} 2026-07-26 ${name}`);
    }
  }else{
    print(Object.keys(contents).join('    '));
  }
},'List directory contents');

register('pwd',()=>{print(cwd)},'Print working directory');

register('cd',(args)=>{
  if(!args[0]){cwd='/home/user';return}
  const resolved=resolvePath(args[0]);
  const node=getNode(resolved);
  if(!node||node.type!=='dir'){print(`cd: ${args[0]}: No such directory`,'err');return}
  cwd=resolved;
},'Change directory');

register('mkdir',(args)=>{
  if(!args[0]){print('mkdir: missing operand','err');return}
  const parts=args[0].split('/').filter(Boolean);
  const dirName=parts.pop();
  const parentPath=resolvePath(parts.join('/')||'.');
  const parent=getNode(parentPath);
  if(!parent||parent.type!=='dir'){print(`mkdir: cannot create directory '${args[0]}': No such file or directory`,'err');return}
  if(parent.children[dirName]){print(`mkdir: cannot create directory '${args[0]}': File exists`,'err');return}
  parent.children[dirName]={type:'dir',children:{}};
},'Create directory');

register('touch',(args)=>{
  if(!args[0]){print('touch: missing operand','err');return}
  const parts=args[0].split('/').filter(Boolean);
  const fileName=parts.pop();
  const parentPath=resolvePath(parts.join('/')||'.');
  const parent=getNode(parentPath);
  if(!parent||parent.type!=='dir'){print(`touch: cannot touch '${args[0]}': No such file or directory`,'err');return}
  if(!parent.children[fileName])parent.children[fileName]={type:'file',content:''};
},'Create empty file');

register('cat',(args)=>{
  if(!args[0]){print('cat: missing operand','err');return}
  const resolved=resolvePath(args[0]);
  const node=getNode(resolved);
  if(!node){print(`cat: ${args[0]}: No such file or directory`,'err');return}
  if(node.type==='dir'){print(`cat: ${args[0]}: Is a directory`,'err');return}
  print(node.content||'');
},'Display file contents');

register('echo',(args)=>{
  const text=args.join(' ');
  // Handle redirect
  if(args.includes('>')){
    const idx=args.indexOf('>');
    const content=args.slice(0,idx).join(' ');
    const fileName=args[idx+1];
    if(fileName){
      const resolved=resolvePath(fileName);
      const node=getNode(resolved);
      if(node&&node.type!=='file'){print('echo: cannot write to directory','err');return}
      const parts=fileName.split('/').filter(Boolean);
      const fname=parts.pop();
      const parentPath=resolvePath(parts.join('/')||'.');
      const parent=getNode(parentPath);
      if(parent&&parent.type==='dir')parent.children[fname]={type:'file',content:content.replace(/^["']|["']$/g,'')};
    }
  }else{
    print(text.replace(/^["']|["']$/g,''));
  }
},'Display text or write to file');

