let events = [];
let currentColor = '#60a5fa';
let zoomLevel = 1;
let minYear = 2020, maxYear = 2030;
const CATEGORIES = { tech: '💻', personal: '👤', work: '💼', education: '📚', health: '💪', travel: '✈️' };

function loadData() {
  try { const d = localStorage.getItem('tl-events'); if (d) { events = JSON.parse(d); calculateRange(); } } catch {}
}
function saveData() { localStorage.setItem('tl-events', JSON.stringify(events)); }

function escapeHTML(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

function calculateRange() {
  if (events.length === 0) { minYear = 2020; maxYear = 2030; return; }
  minYear = Math.min(...events.map(e => e.start));
  maxYear = Math.max(...events.map(e => e.end));
  const padding = Math.max(2, Math.ceil((maxYear - minYear) * 0.1));
  minYear = Math.max(1900, minYear - padding);
  maxYear = Math.min(2100, maxYear + padding);
}

function addEvent() {
  const title = document.getElementById('edTitle').value.trim();
  const start = parseInt(document.getElementById('edStart').value);
  const end = parseInt(document.getElementById('edEnd').value);
  const category = document.getElementById('edCategory').value;
  const desc = document.getElementById('edDesc').value.trim();
  if (!title || isNaN(start) || isNaN(end)) { alert('Please enter title and dates'); return; }
  if (start > end) { alert('Start year must be before end year'); return; }
  events.push({
    id: Date.now().toString(36) + Math.random().toString(36).slice(2,6),
    title, start, end, category, color: currentColor, desc
  });
  calculateRange();
  saveData();
  render();
  document.getElementById('edTitle').value = '';
  document.getElementById('edDesc').value = '';
  document.getElementById('edTitle').focus();
}

function deleteEvent(id) {
  events = events.filter(e => e.id !== id);
  calculateRange();
  saveData();
  render();
}

function render() {
  // Sidebar list
  const list = document.getElementById('eventList');
  if (events.length === 0) list.innerHTML = '<div style="font-size:0.7rem;color:#444;">No events yet</div>';
  else list.innerHTML = events.map(e =>
    `<div class="event-list-item"><span class="dot" style="background:${e.color}"></span><span class="name">${escapeHTML(e.title)}</span><span style="color:#555;font-size:0.6rem">${e.start}-${e.end}</span><button class="del" onclick="deleteEvent('${e.id}')">✕</button></div>`
  ).join('');

  // Timeline
  const container = document.getElementById('timelineContainer');
  document.getElementById('rangeInfo').textContent = events.length ? `${minYear} – ${maxYear} · ${events.length} events` : 'No events';
  if (events.length === 0) {
    container.innerHTML = '<div class="empty-timeline">📅 Add events to build your timeline</div>'; return;
  }

  const yearRange = maxYear - minYear || 1;
  const pxPerYear = Math.max(40, 80 * zoomLevel);
  const totalWidth = yearRange * pxPerYear;

  // Year header
  let html = '<div class="year-header">';
  for (let y = minYear; y <= maxYear; y++) {
    html += `<div class="year-label" style="width:${pxPerYear}px">${y}</div>`;
  }
  html += '</div>';

  // Events lanes
  const lanes = [];
  events.forEach(e => {
    let lane = 0;
    while (true) {
      const conflict = lanes[lane] && lanes[lane].some(ex => e.start < ex.end && e.end > ex.start);
      if (!conflict) break;
      lane++;
    }
    if (!lanes[lane]) lanes[lane] = [];
    lanes[lane].push(e);
  });

  lanes.forEach((laneEvents, laneIdx) => {
    html += `<div class="timeline-lane" style="height:40px">`;
    laneEvents.forEach(e => {
      const left = ((e.start - minYear) / yearRange) * totalWidth;
      const width = Math.max(20, ((e.end - e.start) / yearRange) * totalWidth);
      html += `<div class="timeline-event" style="left:${left}px;width:${width}px;background:${e.color};top:4px" draggable="true" data-id="${e.id}" title="${escapeHTML(e.desc || '')}">
        ${CATEGORIES[e.category] || ''} ${escapeHTML(e.title)}
        <div class="resize-handle left" onmousedown="startResize(event,'${e.id}','left')"></div>
        <div class="resize-handle right" onmousedown="startResize(event,'${e.id}','right')"></div>
      </div>`;
    });
    html += '</div>';
  });

  container.innerHTML = html;

  // Make events draggable
  document.querySelectorAll('.timeline-event').forEach(el => {
    el.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('text/plain', el.dataset.id);
    });
  });
  container.addEventListener('dragover', (e) => e.preventDefault());
  container.addEventListener('drop', (e) => {
    const id = e.dataTransfer.getData('text/plain');
    const ev = events.find(x => x.id === id);
    if (!ev) return;
    const rect = container.getBoundingClientRect();
    const x = e.clientX - rect.left + container.scrollLeft;
    const yearRangePx = yearRange * pxPerYear;
    const startYear = minYear + (x / yearRangePx) * yearRange;
    const duration = ev.end - ev.start;
    ev.start = Math.round(startYear);
    ev.end = ev.start + duration;
    calculateRange();
    saveData();
    render();
  });
}

function startResize(e, id, side) {
  e.preventDefault();
  e.stopPropagation();
  const ev = events.find(x => x.id === id);
  if (!ev) return;
  const startX = e.clientX;
  const origStart = ev.start;
  const origEnd = ev.end;

  const onMove = (me) => {
    const dx = me.clientX - startX;
    const yearRange = maxYear - minYear || 1;
    const pxPerYear = Math.max(40, 80 * zoomLevel);
    const totalWidth = yearRange * pxPerYear;
    const delta = Math.round((dx / totalWidth) * yearRange);
    if (side === 'left') {
      ev.start = Math.max(minYear, Math.min(origEnd - 1, origStart + delta));
    } else {
      ev.end = Math.min(maxYear, Math.max(origStart + 1, origEnd + delta));
    }
    saveData();
    render();
  };
  const onUp = () => { document.removeEventListener('mousemove', onMove); document.removeEventListener('mouseup', onUp); };
