  ctx.fillStyle = '#0f0f1e';
  for (let x = 0; x < w; x += 40) {
    for (let y = 0; y < h; y += 40) {
      if ((Math.floor(x/40) + Math.floor(y/40)) % 2 === 0) {
        ctx.fillRect(x, y, 40, 40);
      }
    }
  }

  // Find active clip at current time
  let activeClip = null;
  for (const clip of project.clips) {
    if (project.currentTime >= clip.start && project.currentTime < clip.start + clip.duration) {
      activeClip = clip;
      break;
    }
  }

  if (activeClip) {
    const clipTime = project.currentTime - activeClip.start;
    const progress = clipTime / activeClip.duration;

    ctx.save();

    // Apply clip effects
    const eff = activeClip.effects || {};
    const scale = (parseInt(eff.scale) || 100) / 100;
    const rotate = parseInt(eff.rotate) || 0;
    const opacity = (parseInt(eff.opacity) || 100) / 100;

    ctx.globalAlpha = opacity;
    ctx.translate(w / 2, h / 2);
