    ctx.fillStyle = grad;
    ctx.fillRect(20, 20, w - 40, h - 40);

    // Draw clip label
    ctx.fillStyle = `hsla(${hue}, 60%, 60%, 0.8)`;
    ctx.font = 'bold 24px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(activeClip.name, w / 2, h / 2 - 10);

    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    ctx.font = '16px Arial';
