    // Progress bar
    ctx.fillStyle = 'rgba(0,217,255,0.2)';
    ctx.fillRect(20, h - 40, w - 40, 8);
    ctx.fillStyle = '#00d9ff';
    ctx.fillRect(20, h - 40, (w - 40) * progress, 8);

    ctx.restore();

    // Apply brightness/contrast/saturation via canvas filter
    const brightness = parseInt(eff.brightness) || 100;
