  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(10, 10, 120, 24);
  ctx.fillStyle = '#00d9ff';
  ctx.font = '12px monospace';
  ctx.textAlign = 'left';
  ctx.fillText(formatTime(project.currentTime), 16, 26);
}

