const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
let elements = [];
let currentTool = 'pen';
let currentColor = '#ffffff';
let currentSize = 3;
let isDrawing = false;
let startX = 0, startY = 0;
let undoStack = [];
let textInput = null;

function resizeCanvas() {
  const rect = canvas.parentElement.getBoundingClientRect();
  canvas.width = rect.width - 2;
  canvas.height = Math.max(400, rect.height || 500);
  canvas.style.height = canvas.height + 'px';
  redraw();
}

function redraw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  elements.forEach(el => {
    ctx.save();
    ctx.strokeStyle = el.color;
    ctx.fillStyle = el.color + '33';
    ctx.lineWidth = el.size;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.font = (el.size * 4) + 'px Segoe UI, Arial, sans-serif';
    ctx.fillStyle = el.color;
    if (el.type === 'pen') {
      ctx.beginPath();
      ctx.moveTo(el.points[0].x, el.points[0].y);
      for (let i = 1; i < el.points.length; i++) ctx.lineTo(el.points[i].x, el.points[i].y);
      ctx.stroke();
    } else if (el.type === 'line') {
      ctx.beginPath();
      ctx.moveTo(el.x1, el.y1);
      ctx.lineTo(el.x2, el.y2);
      ctx.stroke();
    } else if (el.type === 'rect') {
      ctx.beginPath();
      ctx.roundRect(el.x1, el.y1, el.x2 - el.x1, el.y2 - el.y1, 4);
      ctx.fill();
      ctx.stroke();
    } else if (el.type === 'circle') {
      const cx = (el.x1 + el.x2) / 2, cy = (el.y1 + el.y2) / 2;
      const rx = Math.abs(el.x2 - el.x1) / 2, ry = Math.abs(el.y2 - el.y1) / 2;
      ctx.beginPath();
      ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    } else if (el.type === 'text') {
      ctx.fillText(el.text, el.x, el.y);
    } else if (el.type === 'eraser') {
      ctx.strokeStyle = '#1a1a2e';
      ctx.lineWidth = el.size * 2;
      ctx.beginPath();
      ctx.moveTo(el.points[0].x, el.points[0].y);
      for (let i = 1; i < el.points.length; i++) ctx.lineTo(el.points[i].x, el.points[i].y);
      ctx.stroke();
    }
    ctx.restore();
  });
  renderProps();
}

function getCanvasPos(e) {
  const rect = canvas.getBoundingClientRect();
  const scaleX = canvas.width / rect.width;
  const scaleY = canvas.height / rect.height;
  const t = e.touches ? e.touches[0] : e;
  return { x: (t.clientX - rect.left) * scaleX, y: (t.clientY - rect.top) * scaleY };
}

function startDraw(e) {
  e.preventDefault();
  const pos = getCanvasPos(e);
  isDrawing = true;
  startX = pos.x; startY = pos.y;
  if (currentTool === 'pen' || currentTool === 'eraser') {
    elements.push({ type: currentTool, points: [pos], color: currentTool === 'eraser' ? '#1a1a2e' : currentColor, size: currentSize });
  } else if (currentTool === 'text') {
    placeText(pos);
    isDrawing = false;
  }
}

function moveDraw(e) {
  e.preventDefault();
  if (!isDrawing) return;
  const pos = getCanvasPos(e);
  const last = elements[elements.length - 1];
  if (currentTool === 'pen' || currentTool === 'eraser') {
    last.points.push(pos);
    redraw();
  } else {
    last.x2 = pos.x; last.y2 = pos.y;
    redraw();
  }
}

function endDraw(e) {
  if (!isDrawing) return;
  isDrawing = false;
  const last = elements[elements.length - 1];
  if (last && (last.type === 'line' || last.type === 'rect' || last.type === 'circle')) {
    if (Math.abs(last.x2 - last.x1) < 3 && Math.abs(last.y2 - last.y1) < 3) {
      elements.pop();
    }
  }
  undoStack.push(elements.length);
  redraw();
}

function placeText(pos) {
  const text = prompt('Enter text:', 'Hello');
  if (text) {
    elements.push({ type: 'text', x: pos.x, y: pos.y, text, color: currentColor, size: currentSize });
    undoStack.push(elements.length);
    redraw();
  }
}

function setTool(tool) {
  currentTool = tool;
  document.querySelectorAll('.tool-btn').forEach(b => b.classList.toggle('active', b.dataset.tool === tool));
  canvas.style.cursor = tool === 'text' ? 'text' : tool === 'eraser' ? 'cell' : 'crosshair';
  renderProps();
}

function setColor(color) {
  currentColor = color;
  document.querySelectorAll('.color-btn').forEach(b => b.classList.toggle('active', b.dataset.color === color));
  renderProps();
}

function undo() {
  const prev = undoStack.length > 1 ? undoStack[undoStack.length - 2] : 0;
  elements = elements.slice(0, prev);
  undoStack.pop();
  redraw();
}

function clearCanvas() {
  if (elements.length === 0) return;
  if (!confirm('Clear the entire whiteboard?')) return;
  elements = [];
  undoStack = [];
  redraw();
}

function renderProps() {
  const size = document.getElementById('brushSize').value;
  currentSize = parseInt(size);
  const toolNames = { pen: 'Pen', line: 'Line', rect: 'Rectangle', circle: 'Circle', eraser: 'Eraser', text: 'Text' };
  document.getElementById('propTool').textContent = toolNames[currentTool] || currentTool;
  document.getElementById('propColor').textContent = currentColor;
  document.getElementById('propSize').textContent = currentSize;
  document.getElementById('propCount').textContent = elements.length;
  const layer = document.getElementById('layerList');
  if (elements.length === 0) { layer.innerHTML = '<div style="font-size:0.7rem;color:#444;">No elements yet</div>'; return; }
  layer.innerHTML = [...elements].reverse().slice(0, 10).map((el, i) =>
    `<div class="layer-item ${i === 0 ? 'active' : ''}"><span class="layer-color" style="background:${el.color}"></span>${el.type} ${i === 0 ? '(last)' : ''}</div>`
  ).join('');
}

// Touch support
canvas.addEventListener('mousedown', startDraw);
canvas.addEventListener('mousemove', moveDraw);
canvas.addEventListener('mouseup', endDraw);
canvas.addEventListener('mouseleave', endDraw);
canvas.addEventListener('touchstart', startDraw, { passive: false });
canvas.addEventListener('touchmove', moveDraw, { passive: false });
canvas.addEventListener('touchend', endDraw, { passive: false });

window.addEventListener('resize', resizeCanvas);
resizeCanvas();
